// US-11 "My bookings" on a real PostgreSQL (Chapter 11). Three things only the real database can show:
// how node-postgres hands back "date" and "time" columns, whether "cancel" is one atomic step, and the exclusion constraint.
import { describe, it, expect, beforeAll, beforeEach, afterAll } from 'vitest';
import request from 'supertest';
import { bookLab } from '../../src/booking/service.js';
import { createPgRepo } from '../../src/booking/pgRepo.js';
import { cancelMyBooking } from '../../src/booking/myBookings.js';
import { createApp } from '../../src/api/server.js';
import { createAuth } from '../../src/api/auth.js';
import { contractErrors } from '../support/contract.js';
import { openPool } from '../support/db.js';

let pool;
let repo;
beforeAll(async () => {
  pool = openPool();
  repo = createPgRepo(pool);
  await pool.query('TRUNCATE bookings RESTART IDENTITY');   // rows of other test files are committed: clear once (lesson 4.4)
});
beforeEach(() => pool.query('TRUNCATE bookings RESTART IDENTITY'));
afterAll(() => pool.end());

const at = (clock) => new Date('2026-11-16T' + clock + ':00+07:00');
const an = { id: 'an', role: 'STUDENT' };
const input = (overrides = {}) => ({ lab: 'BE-201', date: '2026-11-16', start: '09:00', end: '11:00', seats: 20, role: 'STUDENT', userId: 'an', ...overrides });

// Starter: ONE smoke test — it only checks that the code under test can be imported. It kills no mutant.
// Write the real tests below (see the task). Khởi đầu: MỘT test khói — chỉ kiểm code nạp được, không diệt đột biến nào.
describe('starter', () => {
  it('the code under test can be imported', () => {
    expect(bookLab).toBeDefined();
    expect(createPgRepo).toBeDefined();
    expect(cancelMyBooking).toBeDefined();
    expect(createApp).toBeDefined();
    expect(createAuth).toBeDefined();
    expect(contractErrors).toBeDefined();
    expect(openPool).toBeDefined();
  });
});

// Code Lab · tst-cl-4-1 — LOCAL mutation grader (máy chấm đột biến chạy TRÊN MÁY BẠN).
// Run it inside your labflow-lite project folder:  node cham-tai-may.mjs [test files…]
// (default: the test file(s) of this exercise). Docker must be running (Testcontainers starts PostgreSQL); do not set TEST_DATABASE_URL — every run needs a fresh database.
// What it does — same algorithm as the course's mutation labs: your tests must be GREEN on the correct code, then each
// planted bug is written into its file one at a time (the file is ALWAYS restored, even on Ctrl+C) and your tests must
// turn RED; harmless changes must keep them GREEN. It prints N/N when every check passes.
import { readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

const DE = {
  "id": "tst-cl-4-1",
  "runner": "vitest",
  "config": "vitest.integration.config.js",
  "args": null,
  "tests": [
    "test/integration/myBookings.int.test.js"
  ],
  "dotBien": [
    {
      "file": "src/booking/pgRepo.js",
      "from": "err.code === '23P01'",
      "to": "err.code === '23505'",
      "label": "exclusion violation not recognised"
    },
    {
      "file": "src/booking/service.js",
      "from": "if (err instanceof BookingError) throw err;",
      "to": "",
      "label": "OVERLAP from the database becomes STORAGE_DOWN"
    },
    {
      "file": "src/booking/pgRepo.js",
      "from": "throw new BookingError('OVERLAP', { cause: err });",
      "to": "throw new BookingError('OVERLAP');",
      "label": "OVERLAP loses the database cause"
    },
    {
      "file": "src/booking/pgRepo.js",
      "from": "return { id: rows[0].id, ...b };",
      "to": "return { ...b };",
      "label": "stored booking returned without its id"
    }
  ],
  "voHai": []
};

const tests = process.argv.slice(2).length ? process.argv.slice(2) : DE.tests;
const npx = (args) => spawnSync('npx', args, { encoding: 'utf8', shell: process.platform === 'win32' });
const run = () => (DE.runner === 'playwright'
  ? npx(['playwright', 'test', ...tests, ...(DE.args ?? ['--project=chromium'])])
  : npx(['vitest', 'run', ...(DE.config ? ['--config', DE.config] : []), ...tests, ...(DE.args ?? [])])).status;

let dangSua = null; // { file, goc } — trả lại nếu bị ngắt giữa chừng
const traLai = () => { if (dangSua) { writeFileSync(dangSua.file, dangSua.goc); dangSua = null; } };
process.on('SIGINT', () => { traLai(); process.exit(130); });

function voi(m, fn) {
  const goc = readFileSync(m.file, 'utf8');
  const n = goc.split(m.from).length - 1;
  if (n !== 1) {
    console.log(`  ? "${m.label}": the text to change was found ${n} times in ${m.file} — your file differs from the course version; copy ${m.file} from this exercise's starter and run again`);
    return null;
  }
  dangSua = { file: m.file, goc };
  writeFileSync(m.file, goc.replace(m.from, () => m.to));
  try { return fn(); } finally { traLai(); }
}

console.log(`${DE.id}: ${tests.join(' ')} (${DE.runner})`);
if (run() !== 0) {
  console.log('✘ Your tests are NOT green on the correct code — fix them first (the code has no bug). 0/' + (DE.dotBien.length + DE.voHai.length));
  process.exit(1);
}
console.log('✔ green on the correct code');
let dat = 0;
for (const m of DE.dotBien) {
  const st = voi(m, run);
  if (st != null && st !== 0) dat++;
  console.log(`${st == null ? '?' : st !== 0 ? '✔ killed   ' : '✘ SURVIVED '} ${m.label}`);
}
for (const m of DE.voHai) {
  const st = voi(m, run);
  if (st === 0) dat++;
  console.log(`${st == null ? '?' : st === 0 ? '✔ still green ' : '✘ RED (brittle)'} harmless: ${m.label}`);
}
const tong = DE.dotBien.length + DE.voHai.length;
console.log(`\n${dat}/${tong} ${dat === tong ? '— all mutants killed. Mark the exercise solved on the website.' : '— not yet.'}`);
process.exitCode = dat === tong ? 0 : 1;

